const canales = [
  { handle: '@WesRoth', nombre: 'Wes Roth' },
  { handle: '@xaviermitjana', nombre: 'Xavier Mitjana' },
  { handle: '@DotCSV', nombre: 'Dot CSV' },
  { handle: '@la_inteligencia_artificial', nombre: 'Jon Hernandez' },
  { handle: '@gustavo-entrala', nombre: 'Gustavo Entrala' },
  { handle: '@JoaquinBarbera', nombre: 'Joaquin Barbera' },
  { handle: '@RingaTech', nombre: 'Ringa Tech' },
  { handle: '@GeekGuyLab', nombre: 'GeekGuy Lab' }
];
return canales.map(c => ({ json: c }));

const canales = $('Canales').all();
const entradas = $input.all();
const out = [];
for (let i = 0; i < entradas.length; i++) {
  const html = entradas[i].json.data || '';
  const m = html.match(/"channelId":"(UC[0-9A-Za-z_-]{22})"/) || html.match(/"externalId":"(UC[0-9A-Za-z_-]{22})"/) || html.match(/channel\/(UC[0-9A-Za-z_-]{22})/);
  if (!m) continue;
  out.push({ json: { canal: canales[i] ? canales[i].json.nombre : 'Canal', feedUrl: 'https://www.youtube.com/feeds/videos.xml?channel_id=' + m[1] } });
}
return out;

const HORAS = 168;
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j || !j.title) continue;
  const link = j.link || '';
  const vm = link.match(/[?&]v=([0-9A-Za-z_-]{11})/);
  const videoId = vm ? vm[1] : String(j.id||'').replace('yt:video:','');
  if (!videoId) continue;
  const pub = new Date(j.pubDate || j.isoDate || j.date || Date.now());
  if ((Date.now()-pub.getTime())/3600000 > HORAS) continue;
  out.push({ json: { fuente:'YouTube', origen:(j.author||j.creator||'YouTube'), titulo:j.title, link:'https://www.youtube.com/watch?v='+videoId, fecha:pub.toISOString(), texto:String(j.contentSnippet||j.content||'').slice(0,400), videoId:videoId } });
}
return out;

const feeds = [
  { feedUrl:'https://the-decoder.com/feed/' },
  { feedUrl:'https://techcrunch.com/category/artificial-intelligence/feed/' },
  { feedUrl:'https://arstechnica.com/ai/feed/' },
  { feedUrl:'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml' },
  { feedUrl:'https://openai.com/news/rss.xml' },
  { feedUrl:'https://deepmind.google/blog/rss.xml' },
  { feedUrl:'https://huggingface.co/blog/feed.xml' }
];
return feeds.map(f => ({ json: f }));

const HORAS = 168;
function host(l){
  const s = (typeof l==='string') ? l : (l && l.href ? l.href : String(l||''));
  try { return new URL(s).hostname.replace(/^www\./,''); }
  catch(e){ const m = s.match(/https?:\/\/([^\/]+)/); return m ? m[1].replace(/^www\./,'') : ''; }
}
function origenDe(l, titulo){
  const h = host(l);
  if (!h) return 'Fuente';
  const map = {'techcrunch.com':'TechCrunch','theverge.com':'The Verge','arstechnica.com':'Ars Technica','the-decoder.com':'The Decoder','marktechpost.com':'MarkTechPost','venturebeat.com':'VentureBeat','openai.com':'OpenAI','deepmind.google':'Google DeepMind','huggingface.co':'Hugging Face'};
  if (map[h]) return map[h];
  if (h.indexOf('news.google.com')>=0){ const m=(titulo||'').match(/ - ([^-]+)$/); return m?m[1].trim():'Google News'; }
  return h;
}
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const pub = new Date(j.pubDate || j.isoDate || j.date || Date.now());
  if ((Date.now()-pub.getTime())/3600000 > HORAS) continue;
  const rl = j.link;
  const link = (typeof rl==='string'?rl:(rl&&rl.href?rl.href:'')) || j.guid || '';
  if (!link || !j.title) continue;
  out.push({ json: { fuente:'Articulo', origen: origenDe(link, j.title), titulo:j.title, link:link, fecha:pub.toISOString(), texto:String(j.contentSnippet||j.content||'').slice(0,400), videoId:'' } });
}
return out;

const data = $input.first() ? $input.first().json : {};
const hits = data.hits || [];
const out = [];
for (const h of hits) {
  if (!h.title) continue;
  out.push({ json: { fuente:'Hacker News', origen:'Hacker News', titulo:h.title, link: h.url || ('https://news.ycombinator.com/item?id='+h.objectID), fecha: h.created_at || new Date().toISOString(), texto: String(h.story_text||'').slice(0,400), videoId:'' } });
}
return out;

const items = $input.all().map(i => i.json).filter(v => v && v.titulo);
const POR_ORIGEN = 25;
const grupos = {};
for (const v of items) { (grupos[v.origen] = grupos[v.origen] || []).push(v); }
let lista = [];
let ronda = 0, quedan = true;
while (quedan && lista.length < 160) {
  quedan = false;
  for (const k of Object.keys(grupos)) {
    const g = grupos[k];
    if (ronda < Math.min(g.length, POR_ORIGEN)) { lista.push(g[ronda]); quedan = true; }
  }
  ronda++;
}
const paraModelo = lista.map((v,idx) => ({ id: idx, fuente: v.fuente, origen: v.origen, titulo: v.titulo, resumen: String(v.texto||'').slice(0,200) }));
const prompt = 'Eres el editor de un boletin diario de noticias de IA. Recibes una lista (JSON) de items de varias fuentes (YouTube, Google News, blogs de laboratorios, Hacker News, Reddit). Elige los mas relevantes e importantes para alguien que quiere estar al dia en IA, con criterio periodistico y SIN sesgo de origen (ni por empresa, pais ni plataforma). MAXIMIZA la diversidad de fuentes: no elijas mas de 2 items del mismo origen y procura cubrir fuentes distintas. Criterios de importancia: lanzamientos o updates de modelos, benchmarks, productos o herramientas nuevas, investigacion relevante, y movimientos con impacto practico, de negocio o regulatorio. Prioriza novedad y evita duplicados. Evita hype y clickbait. Incluye al menos 2 items de YouTube (videos) si hay disponibles en la lista. Devuelve unicamente un objeto JSON con una clave llamada seleccion, cuyo valor sea un arreglo con los id (numeros) elegidos, maximo 8. Lista: ' + JSON.stringify(paraModelo);
return [{ json: { items: lista, body: { contents: [ { parts: [ { text: prompt } ] } ], generationConfig: { temperature: 0.2, responseMimeType: 'application/json' } } } }];

const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts[0].text) || '{}';
let sel = [];
try { sel = JSON.parse(raw).seleccion || []; } catch (e) {}
const items = ($('Body Seleccionar').first().json.items) || [];
let eleg = sel.map(id => items[id]).filter(Boolean);
if (eleg.length === 0) eleg = items.slice(0, 8);
const TOTAL = 8, MIN_VIDEOS = 2;
const chosen = new Set(eleg.map(v => v.link));
let videos = eleg.filter(v => v.videoId);
if (videos.length < MIN_VIDEOS) {
  for (const v of items) {
    if (videos.length >= MIN_VIDEOS) break;
    if (v.videoId && !chosen.has(v.link)) { videos.push(v); chosen.add(v.link); }
  }
}
const arts = eleg.filter(v => !v.videoId);
const combinado = videos.concat(arts);
const seen = new Set(); const out = [];
for (const v of combinado) { if (!seen.has(v.link)) { seen.add(v.link); out.push(v); } if (out.length >= TOTAL) break; }
return out.map(v => ({ json: v }));

const items = $input.all().map(i => i.json);
const lista = items.map((v,idx) => ({ id: idx, fuente: v.fuente, origen: v.origen, titulo: v.titulo, link: v.link, contenido: String(v.contenido||v.texto||'').slice(0,6000) }));
const prompt = 'Eres el redactor de un boletin diario de IA. Para cada item recibes su titulo, fuente, link y su contenido (transcripcion de video o texto del articulo). Escribe para cada uno un resumen legible en espanol (es-CL), pensado para leer en el movil sin ver el video ni abrir el articulo. IMPORTANTE: el titular, el resumen y los puntos deben quedar SIEMPRE en espanol; si el contenido de la fuente viene en ingles u otro idioma, traducelo al espanol. Ningun texto de salida puede quedar en ingles. Devuelve unicamente un objeto JSON con la clave resumenes, un arreglo con un objeto por item que tenga: id (el mismo numero que recibiste), titular (claro y directo, sin clickbait), resumen (2 a 4 frases que expliquen que paso y por que importa), y puntos (un arreglo de 2 a 4 strings con los datos o puntos clave mas concretos). Usa solo la informacion del contenido entregado, no inventes. Si el contenido viene vacio, resume a partir del titulo de forma breve. Items: ' + JSON.stringify(lista);
return [{ json: { items: items, body: { contents: [ { parts: [ { text: prompt } ] } ], generationConfig: { temperature: 0.4, responseMimeType: 'application/json' } } } }];

const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts[0].text) || '{}';
let res = [];
try { const o = JSON.parse(raw); res = o.resumenes || (Array.isArray(o) ? o : []); } catch (e) {}
const items = ($('Body Resumen').first().json.items) || [];
return items.map((v,idx) => {
  const r = res.find(x => x && x.id === idx) || res[idx] || {};
  let resumen = (r.resumen && String(r.resumen).trim()) ? String(r.resumen).trim() : '';
  if (!resumen) { resumen = String(v.texto || v.contenido || '').trim().slice(0,240); }
  return { json: Object.assign({}, v, { titular: r.titular || v.titulo, resumen: resumen, puntos: Array.isArray(r.puntos) ? r.puntos : [] }) };
});

const items = $input.all().map(i => i.json);
const fecha = new Date().toLocaleDateString('es-CL', { day:'2-digit', month:'long', year:'numeric' });
const nFuentes = new Set(items.map(v => v.origen)).size;
const nNoticias = items.length;

function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

function card(v){
  const esVideo = !!v.videoId;
  const thumb = esVideo
    ? `<td class="thumb-cell" width="150" valign="top" style="padding-right:14px;">`
      + `<img class="thumb-img" src="https://i.ytimg.com/vi/${v.videoId}/hqdefault.jpg" width="150" style="width:150px;max-width:150px;border-radius:8px;display:block;" alt=""></td>`
    : '';
  const puntos = (v.puntos||[]).map(p => `<li style="margin:4px 0;">${esc(p)}</li>`).join('');
  const puntosHtml = puntos ? `<ul style="margin:8px 0 10px;padding-left:18px;color:#39485a;font-size:14px;line-height:1.55;text-align:justify;">${puntos}</ul>` : '';
  const enlace = esVideo
    ? `<a href="${v.link}" style="color:#0E9A8D;text-decoration:none;font-size:13px;font-weight:700;">Ver el video original &rarr;</a>`
    : `<a href="${v.link}" style="color:#0E9A8D;text-decoration:none;font-size:13px;font-weight:700;">Leer la fuente &rarr;</a>`;
  return `<tr><td style="padding:18px 0;border-bottom:1px solid #E3E8EF;">`
    + `<table class="card-row" role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>`
    + thumb
    + `<td class="text-cell" valign="top">`
    + `<div style="font-size:11px;font-weight:700;color:#0E9A8D;text-transform:uppercase;letter-spacing:.04em;margin-bottom:5px;">${esc(v.origen)}</div>`
    + `<div style="font-size:17px;font-weight:800;color:#0B2545;line-height:1.3;margin-bottom:7px;">${esc(v.titular)}</div>`
    + `<div style="font-size:14px;color:#4C5A6B;line-height:1.6;text-align:justify;">${esc(v.resumen)}</div>`
    + puntosHtml + enlace
    + `</td></tr></table></td></tr>`;
}

const banner = `<tr><td style="padding:18px 0;">`
  + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#0E9A8D;border-radius:12px;"><tr><td style="padding:20px 22px;">`
  + `<div style="font-size:11px;font-weight:800;letter-spacing:.12em;color:#CFF6EF;text-transform:uppercase;">Isaligner &middot; Alineadores invisibles</div>`
  + `<div style="font-size:18px;font-weight:800;color:#ffffff;margin:5px 0 4px;">Transforma tu sonrisa sin brackets</div>`
  + `<div style="font-size:13px;color:#E4FBF7;margin-bottom:12px;">Tratamiento discreto y guiado por especialistas. Primera evaluacion sin costo.</div>`
  + `<a href="https://www.isaligner.com" style="background:#ffffff;color:#0E9A8D;font-weight:800;font-size:13px;text-decoration:none;padding:10px 18px;border-radius:8px;display:inline-block;">Agendar evaluacion &rarr;</a>`
  + `</td></tr></table></td></tr>`;

let filas = '';
items.forEach((v,i) => { filas += card(v); if (i === 1) filas += banner; });

const html = `<!DOCTYPE html>
<html lang="es"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<style>
  body{ margin:0; padding:0; }
  img{ border:0; }
  @media only screen and (max-width:600px){
    .container{ width:100% !important; border-radius:0 !important; }
    .card-row .thumb-cell{ display:block !important; width:100% !important; padding:0 0 12px 0 !important; }
    .card-row .text-cell{ display:block !important; width:100% !important; }
    .thumb-img{ width:100% !important; max-width:100% !important; height:auto !important; }
    .px{ padding-left:18px !important; padding-right:18px !important; }
  }
</style></head>
<body style="margin:0;padding:0;background:#F3F6FA;">
<div style="background:#F3F6FA;padding:16px 0;font-family:'Helvetica Neue',Arial,sans-serif;">
<table class="container" role="presentation" width="600" cellpadding="0" cellspacing="0" align="center" style="max-width:600px;background:#ffffff;margin:0 auto;border-radius:12px;overflow:hidden;">
  <tr><td style="background:#0B2545;padding:16px 24px;">
    <table role="presentation" width="100%"><tr>
      <td style="color:#ffffff;font-weight:800;font-size:16px;letter-spacing:.3px;">isaligner<span style="color:#8FE7DC;">.</span></td>
      <td align="right" style="color:#ffffff;font-size:12px;font-weight:700;letter-spacing:.12em;">PULSO IA &middot; ${fecha}</td>
    </tr></table>
  </td></tr>
  <tr><td class="px" style="padding:24px 24px 6px;">
    <div style="font-size:22px;font-weight:800;color:#0B2545;line-height:1.2;">Lo de la semana en IA</div>
    <div style="font-size:14px;color:#6B7685;margin-top:4px;">${nNoticias} noticias de ${nFuentes} fuentes &middot; resumen de la semana</div>
  </td></tr>
  <tr><td class="px" style="padding:12px 24px 2px;">
    <a href="https://podcast.isaligner.com/" style="display:inline-block;background:#0E9A8D;color:#ffffff;font-weight:800;font-size:14px;text-decoration:none;padding:12px 20px;border-radius:10px;">🎧 Escuchar el podcast de la semana &rarr;</a>
  </td></tr>
  <tr><td class="px" style="padding:6px 24px 0;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0">${filas}</table>
  </td></tr>
  <tr><td style="padding:22px 24px;background:#F3F6FA;text-align:center;">
    <div style="font-weight:800;color:#0B2545;font-size:13px;">isaligner &middot; Pulso IA</div>
    <div style="font-size:11.5px;color:#8695A6;margin-top:4px;">Resumen automatico de noticias de IA &middot; cada martes</div>
  </td></tr>
</table></div></body></html>`;

return [{ json: { html: html } }];

const v = $('Parse seleccion').item.json;
const raw = $json.data || '';
let texto = '';
try { const o = JSON.parse(raw); texto = o.content || o.transcript || ''; } catch (e) { texto = ''; }
texto = String(texto || '').trim();
if (!texto) { texto = String(v.texto || '').trim(); }
return { json: Object.assign({}, v, { contenido: texto.slice(0, 6000) }) };

const v = $('Parse seleccion').item.json;
const raw = $json.data || '';
let texto = String(typeof raw === 'string' ? raw : '').trim();
if (!texto) { texto = String(v.texto || '').trim(); }
return { json: Object.assign({}, v, { contenido: texto.slice(0, 6000) }) };

const items = $input.all().map(i => i.json);
const fmt = d => new Date(d).toLocaleDateString('es-CL', { day:'2-digit', month:'long' });
const fechaFin = new Date();
const fechaIni = new Date(Date.now() - 7*24*3600*1000);
const lista = items.map((v, idx) => ({
  id: idx,
  origen: v.origen,
  titular: v.titular || v.titulo,
  contenido: String(v.contenido || v.texto || '').slice(0, 5000)
}));
const prompt = `Eres el guionista y locutor editorial de un podcast semanal en espanol sobre inteligencia artificial, dirigido a profesionales NO tecnicos (duenos de negocio, gerentes, personas con poco tiempo). Conviertes el material de la semana (del ${fmt(fechaIni)} al ${fmt(fechaFin)}) en un guion locutado, calido y con criterio propio, listo para leerse en voz alta.

RECIBES una lista (JSON) de items ya seleccionados de la semana. Cada item trae ORIGEN, TITULAR y CONTENIDO (texto completo de la fuente). Trabaja SIEMPRE sobre el contenido, no solo el titular. OJO: parte del contenido puede venir en ingles; en ese caso traducelo. TODO el guion se escribe en espanol (es-CL), sin dejar ninguna palabra ni frase en ingles (salvo nombres propios de productos o empresas).

QUE DEBES PRODUCIR: un unico guion locutado en espanol, autocontenido, para unos 8 a 9 minutos de audio (1300 a 1600 palabras).

LA VARA DE CALIDAD (lo mas importante): prioriza lo genuinamente interesante (impacto real, novedad, relevancia para quien dirige un negocio o una clinica). Si un item es flojo, repetido o irrelevante, DESCARTALO aunque venga en la lista. Mejor 4 temas buenos que 8 mediocres. De cada tema explica el "y esto por que me importa?". Nunca te quedes en el dato suelto.

ESTRUCTURA: 1) Saludo breve mas "la foto de la semana" en 1-2 frases (menciona el rango de fechas). 2) Los 3 temas mas importantes, a fondo, con transiciones naturales: que paso (en simple) y por que importa. 3) Barrido rapido: "y en un minuto, el resto de la semana", 3 a 5 titulares de una frase. 4) Cierre: 2 o 3 ideas para llevarse. 5) Despedida ("nos escuchamos la proxima semana").

PAUSAS DE PUBLICIDAD (obligatorio): inserta EXACTAMENTE dos marcas, cada una sola en su linea, en puntos naturales y bien separados: [PAUSA_PUBLICIDAD_1] justo despues del primer tema a fondo, y [PAUSA_PUBLICIDAD_2] justo antes del cierre. NO escribas el texto de la publicidad, solo coloca las marcas.

REGLAS DE ESTILO: espanol hablado, calido y cercano, sin tecnicismos innecesarios (explica toda sigla la primera vez). SIN links, SIN "ve a la fuente", SIN "segun el articulo o video", es 100% autocontenido. Numeros faciles de leer en voz alta (ej.: "diecisiete mil millones de dolares", no la cifra con todos los ceros). Nada de emojis, titulos, vinetas, nombres de seccion ni acotaciones de escena dentro del texto: solo lo que se va a leer en voz alta, mas las dos marcas de pausa. No inventes datos ni cifras; si algo no esta en el material, no lo menciones; si una cifra es dudosa o las fuentes no coinciden, usa lenguaje cualitativo ("del orden de", "cerca de"). Tono equilibrado, ni alarmista ni publicitario.

SALIDA: devuelve UNICAMENTE el texto del guion en espanol (con las dos marcas de pausa en su linea). Nada antes ni despues.

Items: ` + JSON.stringify(lista);
return [{ json: { body: { contents: [ { parts: [ { text: prompt } ] } ], generationConfig: { temperature: 0.55, maxOutputTokens: 8192 } } } }];

const c = $json.candidates && $json.candidates[0] && $json.candidates[0].content;
const raw = (c && c.parts && c.parts[0] && c.parts[0].text) || '';
return [{ json: { guion: String(raw).trim() } }];

const guion = ($input.first() && $input.first().json.guion) || '';
const CUNA1 = 'Una pausa, de la mano de Isaligner: alineadores invisibles con especialistas en ortodoncia, en Providencia y Los Ángeles. Convenios con seguros y facilidades de pago.';
const CUNA2 = 'Antes de terminar: Isaligner, tu sonrisa alineada sin complicarte. Agenda en isaligner punto com o escríbenos en Instagram, arroba isaligner. Te esperamos en Providencia y Los Ángeles.';
let seg1 = guion, seg2 = '', seg3 = '';
const M1 = '[PAUSA_PUBLICIDAD_1]', M2 = '[PAUSA_PUBLICIDAD_2]';
const i1 = guion.indexOf(M1), i2 = guion.indexOf(M2);
if (i1 >= 0 && i2 > i1) {
  seg1 = guion.slice(0, i1);
  seg2 = guion.slice(i1 + M1.length, i2);
  seg3 = guion.slice(i2 + M2.length);
}
const limpia = s => String(s).replace(/\[PAUSA_PUBLICIDAD_\d\]/g, '').trim();
const voice = { stability: 0.5, similarity_boost: 0.75, style: 0.0, use_speaker_boost: true };
const piezas = [
  { tipo: 'narracion', texto: limpia(seg1) },
  { tipo: 'cuna', texto: CUNA1 },
  { tipo: 'narracion', texto: limpia(seg2) },
  { tipo: 'cuna', texto: CUNA2 },
  { tipo: 'narracion', texto: limpia(seg3) }
].filter(p => p.texto && p.texto.length > 0);
return piezas.map((p, idx) => ({ json: { orden: idx, tipo: p.tipo, texto: p.texto, body: { text: p.texto, model_id: 'eleven_multilingual_v2', voice_settings: voice } } }));

const items = $input.all();
const piezas = $('Partir guion').all().map(p => p.json);
let cortIdx = -1;
for (let i = 0; i < items.length; i++) { if (items[i].json && items[i].json.tipo === 'cortina') { cortIdx = i; break; } }
if (cortIdx < 0) cortIdx = items.length - 1;
const getBuf = async (i) => {
  const bin = (items[i] && items[i].binary) || {};
  const props = Object.keys(bin);
  const prop = props.indexOf('data') >= 0 ? 'data' : props[0];
  if (!prop) return Buffer.alloc(0);
  let b = null;
  try { b = await this.helpers.getBinaryDataBuffer(i, prop); } catch (e) {}
  if ((!b || !b.length) && bin[prop] && bin[prop].data) { try { b = Buffer.from(bin[prop].data, 'base64'); } catch (e) {} }
  return (b && b.length) ? b : Buffer.alloc(0);
};
const cortBuf = await getBuf(cortIdx);
const segIdx = [];
for (let i = 0; i < items.length; i++) { if (i !== cortIdx) segIdx.push(i); }
const partes = [];
for (let k = 0; k < segIdx.length; k++) {
  const tipo = (piezas[k] && piezas[k].tipo) || 'narracion';
  const buf = await getBuf(segIdx[k]);
  if (!buf.length) continue;
  if (tipo === 'cuna') {
    if (cortBuf.length) partes.push(cortBuf);
    partes.push(buf);
    if (cortBuf.length) partes.push(cortBuf);
  } else {
    partes.push(buf);
  }
}
const merged = Buffer.concat(partes);
